-- The schema a v1.0.4 database had before schema versioning existed.
-- One statement per line: the test runner executes each non-comment line as-is.
PRAGMA user_version = 1;
CREATE TABLE IF NOT EXISTS products (id INTEGER PRIMARY KEY AUTOINCREMENT,barcode TEXT UNIQUE,name TEXT NOT NULL,cost_price_cents INTEGER NOT NULL DEFAULT 0,sale_price_cents INTEGER NOT NULL DEFAULT 0,quantity INTEGER NOT NULL DEFAULT 0,unit TEXT NOT NULL DEFAULT '',package_size INTEGER NOT NULL DEFAULT 1,active INTEGER NOT NULL DEFAULT 1,sold_by_weight INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sales (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT NOT NULL,total_cents INTEGER NOT NULL,device_id TEXT NOT NULL,oversold INTEGER NOT NULL DEFAULT 0,reversed_sale_id INTEGER NOT NULL DEFAULT 0,occasion_id INTEGER);
CREATE TABLE IF NOT EXISTS occasions (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,icon TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sale_items (id INTEGER PRIMARY KEY AUTOINCREMENT,sale_id INTEGER NOT NULL REFERENCES sales(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL,unit_price_cents INTEGER NOT NULL,unit_cost_cents INTEGER NOT NULL,reversed_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS customers (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS customer_transactions (id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER NOT NULL REFERENCES customers(id),amount_cents INTEGER NOT NULL,created_at TEXT NOT NULL,reversed_transaction_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS customer_transaction_items (id INTEGER PRIMARY KEY AUTOINCREMENT,customer_transaction_id INTEGER NOT NULL REFERENCES customer_transactions(id),product_id INTEGER NOT NULL REFERENCES products(id),quantity INTEGER NOT NULL,unit_price_cents INTEGER NOT NULL,unit_cost_cents INTEGER NOT NULL,reversed_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS suppliers (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',opening_balance_cents INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER NOT NULL REFERENCES customers(id),amount_cents INTEGER NOT NULL,created_at TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',reversed_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS expenses (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT NOT NULL,label TEXT NOT NULL,amount_cents INTEGER NOT NULL,reversed_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS owner_drawings (id INTEGER PRIMARY KEY AUTOINCREMENT,created_at TEXT NOT NULL,amount_cents INTEGER NOT NULL,note TEXT NOT NULL DEFAULT '',reversed_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS stock_movements (id INTEGER PRIMARY KEY AUTOINCREMENT,product_id INTEGER NOT NULL REFERENCES products(id),delta INTEGER NOT NULL,reason TEXT NOT NULL,reference TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,reversed_id INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS cash_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT,opened_at TEXT NOT NULL,opening_float_cents INTEGER NOT NULL,closed_at TEXT NULL,closing_counted_cents INTEGER NULL,expected_cents INTEGER NULL,variance_cents INTEGER NULL,status TEXT NOT NULL DEFAULT 'open');
CREATE TABLE IF NOT EXISTS cash_movements (id INTEGER PRIMARY KEY AUTOINCREMENT,session_id INTEGER NOT NULL REFERENCES cash_sessions(id),type TEXT NOT NULL,amount_cents INTEGER NOT NULL,created_at TEXT NOT NULL,note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,role TEXT NOT NULL,pin TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE TABLE IF NOT EXISTS admin_secrets (user_id INTEGER PRIMARY KEY REFERENCES users(id),master_hash TEXT NOT NULL,master_salt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS devices (id INTEGER PRIMARY KEY AUTOINCREMENT,device_id TEXT UNIQUE NOT NULL,auth_token TEXT NOT NULL,paired_at TEXT NOT NULL,last_seen_at TEXT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS zakat_settings (id INTEGER PRIMARY KEY AUTOINCREMENT,key TEXT UNIQUE NOT NULL,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settings (id INTEGER PRIMARY KEY AUTOINCREMENT,key TEXT UNIQUE NOT NULL,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sync_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT,op_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS applied_ops (id INTEGER PRIMARY KEY AUTOINCREMENT,device_id TEXT NOT NULL,op_id INTEGER NOT NULL,op_type INTEGER NOT NULL,entity_id INTEGER NOT NULL,total_cents INTEGER NOT NULL,cogs_cents INTEGER NOT NULL DEFAULT 0,applied_at TEXT NOT NULL,UNIQUE(device_id, op_id));
CREATE TABLE IF NOT EXISTS sync_sequence (id INTEGER PRIMARY KEY CHECK (id = 1),value INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS purchases (id INTEGER PRIMARY KEY AUTOINCREMENT,supplier_id INTEGER NOT NULL,invoice_number TEXT NOT NULL DEFAULT '',purchased_at TEXT NOT NULL,subtotal_cents INTEGER NOT NULL,vat_cents INTEGER NOT NULL DEFAULT 0,total_cents INTEGER NOT NULL,paid_cents INTEGER NOT NULL DEFAULT 0,add_to_stock INTEGER NOT NULL DEFAULT 1,note TEXT NOT NULL DEFAULT '',occasion_id INTEGER,created_at TEXT NOT NULL,FOREIGN KEY (supplier_id) REFERENCES suppliers(id));
CREATE TABLE IF NOT EXISTS purchase_items (id INTEGER PRIMARY KEY AUTOINCREMENT,purchase_id INTEGER NOT NULL,product_id INTEGER,description TEXT NOT NULL DEFAULT '',quantity INTEGER NOT NULL,unit TEXT NOT NULL DEFAULT 'piece',unit_price_cents INTEGER NOT NULL,total_cents INTEGER NOT NULL,FOREIGN KEY (purchase_id) REFERENCES purchases(id),FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE IF NOT EXISTS supplier_payments (id INTEGER PRIMARY KEY AUTOINCREMENT,supplier_id INTEGER NOT NULL,purchase_id INTEGER,amount_cents INTEGER NOT NULL,paid_at TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,FOREIGN KEY (supplier_id) REFERENCES suppliers(id),FOREIGN KEY (purchase_id) REFERENCES purchases(id));
CREATE TABLE IF NOT EXISTS supplier_returns (id INTEGER PRIMARY KEY AUTOINCREMENT,supplier_id INTEGER NOT NULL,purchase_id INTEGER,amount_cents INTEGER NOT NULL,returned_at TEXT NOT NULL,remove_from_stock INTEGER NOT NULL DEFAULT 1,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,FOREIGN KEY (supplier_id) REFERENCES suppliers(id),FOREIGN KEY (purchase_id) REFERENCES purchases(id));
CREATE TABLE IF NOT EXISTS supplier_return_items (id INTEGER PRIMARY KEY AUTOINCREMENT,return_id INTEGER NOT NULL,product_id INTEGER,quantity INTEGER NOT NULL,unit_price_cents INTEGER NOT NULL,total_cents INTEGER NOT NULL,FOREIGN KEY (return_id) REFERENCES supplier_returns(id),FOREIGN KEY (product_id) REFERENCES products(id));
INSERT OR IGNORE INTO sync_sequence (id, value) VALUES (1, 0);
CREATE TRIGGER IF NOT EXISTS trg_stock_after_insert AFTER INSERT ON stock_movements BEGIN UPDATE products SET quantity = quantity + NEW.delta WHERE id = NEW.product_id; END;
CREATE INDEX IF NOT EXISTS idx_sale_items_sale_id ON sale_items(sale_id);
CREATE INDEX IF NOT EXISTS idx_customer_transactions_customer_id ON customer_transactions(customer_id);
CREATE INDEX IF NOT EXISTS idx_stock_movements_product_id ON stock_movements(product_id);
CREATE INDEX IF NOT EXISTS idx_cash_movements_session_id ON cash_movements(session_id);
CREATE INDEX IF NOT EXISTS idx_applied_ops_device_op ON applied_ops(device_id, op_id);
CREATE INDEX IF NOT EXISTS idx_purchases_supplier ON purchases(supplier_id, purchased_at DESC);
CREATE INDEX IF NOT EXISTS idx_purchase_items_purchase ON purchase_items(purchase_id);
CREATE INDEX IF NOT EXISTS idx_supplier_payments_supplier ON supplier_payments(supplier_id, paid_at DESC);
CREATE INDEX IF NOT EXISTS idx_supplier_payments_purchase ON supplier_payments(purchase_id);
CREATE INDEX IF NOT EXISTS idx_supplier_returns_supplier ON supplier_returns(supplier_id, returned_at DESC);
CREATE INDEX IF NOT EXISTS idx_supplier_return_items_return ON supplier_return_items(return_id);
CREATE INDEX IF NOT EXISTS idx_occasions_active ON occasions(active, starts_at);
CREATE UNIQUE INDEX IF NOT EXISTS idx_cash_sessions_one_open ON cash_sessions(status) WHERE status = 'open';
